import{z as n,x as s,o as e,c as p,q as r,j as o,D as E,d as A,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"代工路线对比","description":"","frontmatter":{"title":"代工路线对比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/foundry-roadmap-compare.md","filePath":"litho/foundry-roadmap-compare.md","lastUpdated":1791063341000}'),d={name:"litho/foundry-roadmap-compare.md"};function B(h,a,m,D,_,C){const t=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="代工路线对比" tabindex="-1">代工路线对比 <a class="header-anchor" href="#代工路线对比" aria-label="Permalink to &quot;代工路线对比&quot;">​</a></h1><div class="epigraph"><p>同一世代名下，EUV 层数、高 NA 时间表、GAA/CFET 与背面电源可以完全不同；对比要按层策略，不按广告同步。</p><footer>—— 对照领先代工公开节点路径的结构差异；不编造未公布层数</footer></div><p><a href="/litho/pfas-resist-regulation">上一课</a>把材料风险放进规划。缺口是各厂怎么走。本课钉代工路线对比。存储器路径不同，留给<a href="/litho/memory-litho-dram-nand">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TSMC、Intel、Samsung 等公开叙事在：EUV 插入早晚、是否 High-NA、FinFET 到 GAA 的时间、背面电源、命名（N3/N2 vs 18A）。光刻含义：EUV 层数改交叉与瓶颈；High-NA 改半场与薄胶；GAA 改切线与片间距图形。对比必须引用当时公开材料并注明年份，不能把传闻层表当课文本体。</p>',5)),(e(),o(l,null,{default:E(()=>[i(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20NODE%5B%22%E5%90%8C%E4%B8%80%E4%B8%96%E4%BB%A3%E5%90%8D%EF%BC%88N3%20%2F%20N2%20%2F%2018A%EF%BC%89%22%5D%20--%3E%20A1%5B%22%E8%BD%B4%E4%B8%80%EF%BC%9AEUV%20%E6%8F%92%E5%85%A5%E6%97%A9%E6%99%9A%E4%B8%8E%E5%B1%82%E7%AD%96%E7%95%A5%22%5D%0A%20%20NODE%20--%3E%20A2%5B%22%E8%BD%B4%E4%BA%8C%EF%BC%9AHigh-NA%20%E6%98%AF%E7%A0%94%E7%A9%B6%E8%BF%98%E6%98%AF%E6%8F%92%E5%85%A5%E8%AE%A1%E5%88%92%22%5D%0A%20%20NODE%20--%3E%20A3%5B%22%E8%BD%B4%E4%B8%89%EF%BC%9AFinFET%20%E5%88%B0%20GAA%20%2F%20CFET%20%E7%9A%84%E6%97%B6%E9%97%B4%22%5D%0A%20%20NODE%20--%3E%20A4%5B%22%E8%BD%B4%E5%9B%9B%EF%BC%9A%E8%83%8C%E9%9D%A2%E4%BE%9B%E7%94%B5%E4%B8%8E%E5%B0%81%E8%A3%85%E9%94%AE%E5%90%88%22%5D%0A%20%20A1%20--%3E%20CMP%5B%22%E9%80%90%E8%BD%B4%E5%AF%B9%E6%AF%94%EF%BC%8C%E8%80%8C%E9%9D%9E%E6%8C%89%E5%90%8D%E5%AD%97%E5%AF%B9%E9%BD%90%22%5D%0A%20%20A2%20--%3E%20CMP%0A%20%20A3%20--%3E%20CMP%0A%20%20A4%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>这张图回答的问题是：比较代工路线时到底该比较什么。世代名只是入口，真正的比较要落到四条物理与工艺轴上——每条轴独立演化，所以三家在同一世代名下的实际内容可以差很远。</p><p><span class="marginnote">术语翻译：N3、N2、18A 这类名字是各厂自己的商品名，不对应同一个物理栅长，也不保证彼此可比——类似鞋码，欧码和美码数字对不上。要比较就得用层数、节距、器件架构这些「脚的实际尺寸」，而不是码号本身。</span></p><p>缺口是<strong>路径分叉</strong>，不是谁赢。把三家画成同一条 IRDS 线，会误导 DTCO。</p><h3 id="公开可说的" tabindex="-1">公开可说的 <a class="header-anchor" href="#公开可说的" aria-label="Permalink to &quot;公开可说的&quot;">​</a></h3><p>结构差异类型：先全 DUV 多重再插 EUV vs 较早 EUV；High-NA 作为研究 vs 插入计划；混跑策略。具体层清单以各厂公开为准，本课不发明。</p><p><span class="marginnote">客户选择代工等于选择一套光刻约束（设计规则、EUV 随机、拼接）。IP 可移植性有光刻成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列比较轴：CPP/MMP（若公开）、EUV 使用、High-NA、器件架构、封装/键合。每轴用公开出处。内部决策仍用自己的交叉模型。</p><p><span class="marginnote">常见误区：初学者容易把三家路线表竖着对齐年份、横着比进度，得出「某厂落后半年」。实际上插入顺序不同——先 DUV 多重图形再上 EUV，或反之——会让同名节点下的层数、成本与随机风险结构完全不同。横向对齐年份本身就是要避免的读法。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>各厂资本存量（已有浸没台数、EUV 台数）、客户组合、风险偏好，使同一物理极限下的插入顺序不同。这是经济与组织，不是光学常数不同。</p><p><span class="marginnote">直觉类比：已经装了一屋子传统烤箱的面包房，不会马上换新式炉子，而是把旧炉子的产能用尽再升级——「先多重图形后 EUV」就是同一本账。插入顺序由资产负债表和风险偏好决定，不等于谁不懂光学。</span></p>',12)),(e(),o(l,null,{default:E(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E6%9E%81%E9%99%90%22%5D%20--%3E%20PATH%5B%22%E6%8F%92%E5%85%A5%E9%A1%BA%E5%BA%8F%E5%88%86%E5%8F%89%22%5D%0A%20%20CAP%5B%22%E5%B7%B2%E6%9C%89%E6%9C%BA%E5%8F%B0%E5%AD%98%E9%87%8F%22%5D%20--%3E%20PATH%0A%20%20PATH%20--%3E%20DR%5B%22%E4%B8%8D%E5%90%8C%20PDK%20%2F%20%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不排名。不泄露非公开层数。路线会改，课文钉轴而不是钉某年新闻。</p><p>后课默认：逻辑代工路径分叉；下一课 DRAM/NAND 的光刻负担与逻辑不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代工对比按 EUV 层策略、High-NA、器件架构等轴，不按商品名同步。</li><li>只引用公开材料并注明年份。</li><li>分叉来自资本存量与风险，不来自另一套光学。</li><li>出处：领先代工公开节点叙事的结构对照。</li></ul>',5))])}const T=n(d,[["render",B]]);export{u as __pageData,T as default};
